widget.solution:
from math import erf, exp, log, sqrt

def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def quick_prices(S, K, r, sigma, T):
    d2 = (log(S / K) + (r - sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    fwd = S - K * exp(-r * T)
    dig_c = exp(-r * T) * norm_cdf(d2)
    dig_p = exp(-r * T) * norm_cdf(-d2)
    power = S ** 2 * exp((r + sigma ** 2) * T)
    return [fwd, dig_c, dig_p, power]
